import React, {useState} from 'react'
import {Breadcrumbs, Heading, Label, Link, Stack, UnderlineNav} from '@primer/react'
import {PersonIcon, VersionsIcon} from '@primer/octicons-react'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import {LicenseHistoryContainer} from './components/LicenseHistoryContainer'
import type {EnterpriseCloudSummaryData} from './types/enterprise-cloud-summary-data'
import {LicenseeListContainer} from './components/LicenseeListContainer'
import {SummarySectionContainer} from './components/SummarySectionContainer'
import {useSearchParams} from '@github-ui/react-router'
import styles from './components/LicenseHistory.module.css'
import {SubPageLayout} from '@github-ui/licensing-common/components/SubPageLayout'

export type EnterpriseCloudDetailsProps = {
  enterpriseContactUrl: string
  isStafftools: boolean
  slug: string
  stafftoolsBlaAuditLogPath?: string
  isVssEnabled: boolean
  isHistoryEnabled: boolean
} & EnterpriseCloudSummaryData

export function EnterpriseCloudDetails(props: EnterpriseCloudDetailsProps) {
  const [refreshToken, setRefreshToken] = useState(0)
  const [searchParams, setSearchParams] = useSearchParams()
  const availableTabs = [props.isVssEnabled && 'users', props.isHistoryEnabled && 'history'].filter(Boolean)
  const hasMultipleTabs = availableTabs.length > 1
  const defaultTab = props.isVssEnabled ? 'users' : props.isHistoryEnabled ? 'history' : 'users'
  const selectedTab = searchParams.get('tab') || defaultTab

  const handleTabChange = (event: React.MouseEvent, tab: string) => {
    event.preventDefault()
    setSearchParams(prev => {
      prev.set('tab', tab)
      return prev
    })
  }
  const getTabUrl = (tab: string) => {
    const currentParams = new URLSearchParams(searchParams)
    currentParams.set('tab', tab)
    return `?${currentParams.toString()}`
  }

  return (
    <SubPageLayout
      enterpriseContactUrl={props.enterpriseContactUrl}
      isStafftools={props.isStafftools}
      slug={props.slug}
      header={<Header />}
      containerProps={{'data-testid': 'licensing-cloud-details'}}
    >
      <Stack justify="space-between" direction="horizontal" align="baseline" className="mt-2 mb-3">
        <Heading as="h1">Enterprise Cloud</Heading>
        {props.isStafftools && (
          <Link href={props.stafftoolsBlaAuditLogPath}>Bundled License Assignments Audit Log</Link>
        )}
      </Stack>
      <SummarySectionContainer initialSummaryData={props} refreshToken={refreshToken} />

      {hasMultipleTabs && (
        <div className="mt-3">
          <div className="pb-2">
            <UnderlineNav aria-label="Access Tabs">
              {props.isVssEnabled && (
                <UnderlineNav.Item
                  href={getTabUrl('users')}
                  aria-current={selectedTab === 'users' ? 'page' : undefined}
                  onClick={e => handleTabChange(e, 'users')}
                  icon={<PersonIcon size={16} />}
                  data-testid="licensing-enterprise-users-tab"
                >
                  Users
                </UnderlineNav.Item>
              )}
              {props.isHistoryEnabled && (
                <UnderlineNav.Item
                  href={getTabUrl('history')}
                  aria-current={selectedTab === 'history' ? 'page' : undefined}
                  onClick={e => handleTabChange(e, 'history')}
                  icon={<VersionsIcon size={16} />}
                  data-testid="licensing-enterprise-history-tab"
                >
                  <span>
                    History <Label variant="success">Preview</Label>
                  </span>
                </UnderlineNav.Item>
              )}
            </UnderlineNav>
          </div>

          {selectedTab === 'users' && props.isVssEnabled && (
            <div data-testid="licensing-enterprise-users-content">
              <LicenseeListContainer
                isVolumeLicensed={props.isVolumeLicensed}
                unitCost={props.unitCost}
                onLicenseeChange={() => {
                  setRefreshToken(prev => prev + 1)
                }}
              />
            </div>
          )}

          {selectedTab === 'history' && props.isHistoryEnabled && (
            <div data-testid="licensing-enterprise-history-content">
              <span className={styles.headerDescription} style={{display: 'block', marginBottom: '16px'}}>
                Daily snapshots of license additions and removals to monitor usage over time.
              </span>
              <LicenseHistoryContainer />
            </div>
          )}
        </div>
      )}

      {!hasMultipleTabs && (
        <div className="mt-3">
          {/* Show only history content with header */}
          {!props.isVssEnabled && props.isHistoryEnabled && (
            <div data-testid="licensing-enterprise-history-content">
              <div className="mb-4">
                <Stack direction="horizontal" align="center" gap="condensed">
                  <Heading as="h1">License History</Heading>
                  <Label variant="success" size="large">
                    Preview
                  </Label>
                </Stack>
                <span className={styles.headerDescription}>
                  Daily snapshots of license additions and removals to monitor usage over time.
                </span>
              </div>
              <LicenseHistoryContainer />
            </div>
          )}

          {props.isVssEnabled && !props.isHistoryEnabled && (
            <div data-testid="licensing-enterprise-users-content">
              <LicenseeListContainer
                isVolumeLicensed={props.isVolumeLicensed}
                unitCost={props.unitCost}
                onLicenseeChange={() => {
                  setRefreshToken(prev => prev + 1)
                }}
              />
            </div>
          )}
        </div>
      )}
    </SubPageLayout>
  )
}

function Header() {
  const {basePath} = useNavigation()
  return (
    <Breadcrumbs>
      <Breadcrumbs.Item href={`${basePath}/licensing`}>Licensing</Breadcrumbs.Item>
      <Breadcrumbs.Item selected>Enterprise Cloud</Breadcrumbs.Item>
    </Breadcrumbs>
  )
}

try{ EnterpriseCloudDetails.displayName ||= 'EnterpriseCloudDetails' } catch {}
try{ Header.displayName ||= 'Header' } catch {}