import {useState} from 'react'
import {Dialog, Stack, Banner} from '@primer/react'
import {clsx} from 'clsx'
import {reactFetchJSON} from '@github-ui/verified-fetch'
import styles from './VisualStudioMatchDialog.module.css'
import {VisualStudioMatchPickerContainer} from './VisualStudioMatchPickerContainer'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import type {SubscriptionIdentifier} from '../types/subscription-identifier'

export interface VisualStudioMatchDialogProps {
  currentSubscriptionIdentifier?: SubscriptionIdentifier | null
  errorMessage: string | null
  hasVssLicensesLeft: boolean
  isSaving: boolean
  isVolumeLicensed: boolean
  licenseeFullName: string
  licenseeLogin: string
  licenseeId: string
  mode: 'create' | 'update'
  unitCost: string
  onClose: () => void
  onSuccess: () => void
  onDismissError: () => void
}

export function VisualStudioMatchDialog(props: VisualStudioMatchDialogProps) {
  const {slug} = useNavigation()
  // Holds the chosen Visual Studio subscription identifier (BLA ID, plus the matched email or UPN)
  const [selectedSubscriptionIdentifier, setSelectedSubscriptionIdentifier] = useState<SubscriptionIdentifier | null>(
    props.mode === 'update' ? props.currentSubscriptionIdentifier || null : null,
  )
  const [showSubscriptionIdentifierFieldError, setShowSubscriptionIdentifierFieldError] = useState(false)
  const [isSaving, setIsSaving] = useState(false)

  const saveCreate = async (identifier: SubscriptionIdentifier) => {
    const url = `/enterprises/${encodeURIComponent(slug)}/licensing/bundled_license_assignments`
    const body = {
      id: identifier.id,
      user_id: props.licenseeId,
    }
    await reactFetchJSON(url, {
      method: 'POST',
      body,
    })
  }

  const saveUpdate = async (identifier: SubscriptionIdentifier) => {
    const url = `/enterprises/${encodeURIComponent(slug)}/licensing/bundled_license_assignments/${identifier.id}`
    const body = {
      user_id: props.licenseeId,
    }
    await reactFetchJSON(url, {
      method: 'PUT',
      body,
    })
  }

  const handleConfirm = async () => {
    if (!selectedSubscriptionIdentifier) {
      setShowSubscriptionIdentifierFieldError(true)
      return
    }

    // If the selected subscription is the same as the current match, close the dialog without making a request
    if (
      props.mode === 'update' &&
      props.currentSubscriptionIdentifier &&
      selectedSubscriptionIdentifier &&
      selectedSubscriptionIdentifier.id === props.currentSubscriptionIdentifier.id
    ) {
      props.onClose()
      return
    }

    setIsSaving(true)
    try {
      if (props.mode === 'update') {
        await saveUpdate(selectedSubscriptionIdentifier)
      } else {
        await saveCreate(selectedSubscriptionIdentifier)
      }
      props.onSuccess()
    } catch (err) {
      // eslint-disable-next-line no-console
      console.error('Error saving Visual Studio license change:', err)
      props.onDismissError()
    } finally {
      setIsSaving(false)
    }
  }

  return (
    <Dialog
      title={props.mode === 'create' ? 'Change to Visual Studio license' : 'Update Visual Studio email'}
      subtitle={
        props.mode === 'create'
          ? `You're about to convert this user's current${
              props.isVolumeLicensed ? '' : ' metered'
            } GitHub Enterprise license to a Visual Studio subscription.`
          : undefined
      }
      width="large"
      onClose={props.onClose}
      footerButtons={[
        {buttonType: 'default', content: 'Cancel', onClick: props.onClose},
        {
          buttonType: 'primary',
          content: props.mode === 'create' ? 'Confirm change' : 'Update email',
          disabled: !props.hasVssLicensesLeft || isSaving,
          onClick: handleConfirm,
        },
      ]}
    >
      <Stack direction="vertical">
        {props.errorMessage && (
          <Banner variant="critical" title="Error saving license change" hideTitle onDismiss={props.onDismissError}>
            {props.errorMessage}
          </Banner>
        )}
        {!props.hasVssLicensesLeft && (
          <Banner variant="warning" title="No Visual Studio licenses available" hideTitle>
            You&apos;ve used up all your available Visual Studio licenses. To manage your licenses, visit your Visual
            Studio admin portal.
          </Banner>
        )}
        {props.mode === 'create' && (
          <Stack direction="horizontal" gap="normal">
            <Stack direction="vertical" gap="none" className={clsx(styles.vsDialogCol)}>
              <div className="f6 fgColor-muted text-semibold">Current:</div>
              <div className="f5 text-semibold">GitHub Enterprise</div>
              {!props.isVolumeLicensed && <div className="f6 fgColor-muted">Billed at {props.unitCost}</div>}
            </Stack>
            <Stack direction="vertical" gap="none" className={clsx(styles.vsDialogCol)}>
              <div className="f6 fgColor-muted text-semibold">New:</div>
              <div className="f5 text-semibold">Visual Studio subscription</div>
              {props.hasVssLicensesLeft ? (
                <div className="f6 fgColor-muted">Managed by your Visual Studio agreement</div>
              ) : (
                <div className="f6 fgColor-attention">0 licenses remaining</div>
              )}
            </Stack>
          </Stack>
        )}
        {props.hasVssLicensesLeft && (
          <VisualStudioMatchPickerContainer
            selectedSubscriptionIdentifier={selectedSubscriptionIdentifier}
            onChange={setSelectedSubscriptionIdentifier}
            showError={showSubscriptionIdentifierFieldError && !selectedSubscriptionIdentifier}
            onUserInput={() => setShowSubscriptionIdentifierFieldError(false)}
            currentMatch={
              props.mode === 'update' && props.currentSubscriptionIdentifier
                ? props.currentSubscriptionIdentifier
                : undefined
            }
            caption={
              <>
                Enter the login email address associated with a Visual Studio subscription associated with{' '}
                <span className="text-semibold">{props.licenseeFullName}</span> (
                <span className="text-semibold">{props.licenseeLogin}</span>).
              </>
            }
          />
        )}
      </Stack>
    </Dialog>
  )
}

try{ VisualStudioMatchDialog.displayName ||= 'VisualStudioMatchDialog' } catch {}