import type {ReactNode} from 'react'
import {Spinner, Stack} from '@primer/react'
import {Blankslate} from '@primer/react/experimental'
import {AlertIcon} from '@primer/octicons-react'
import {clsx} from 'clsx'

import {useNavigation} from '../contexts/NavigationContext'
import styles from './SummarySection.module.css'

export interface SummarySectionProps {
  isError?: boolean
  isLoading?: boolean
  summaries: readonly ReactNode[]
  errorHeading?: ReactNode
  errorDescription?: ReactNode
  supportContactUrl?: string
}

export function SummarySection({
  isError = false,
  isLoading = false,
  summaries,
  errorHeading,
  errorDescription,
  supportContactUrl,
}: SummarySectionProps) {
  const {enterpriseContactUrl} = useNavigation()
  const contactUrl = supportContactUrl || enterpriseContactUrl || 'https://support.github.com/contact'

  if (isLoading) {
    return (
      <div className="mb-3">
        <div className="Box d-flex flex-justify-center p-5" role="status" aria-live="polite">
          <Spinner size="large" srText="Loading summaries" />
        </div>
      </div>
    )
  }

  if (isError) {
    return (
      <div className="mb-3">
        <Blankslate border>
          <Blankslate.Visual>
            <AlertIcon size="medium" className="fgColor-muted" />
          </Blankslate.Visual>
          <Blankslate.Heading>
            {errorHeading ?? 'License usage and payment summaries cannot be loaded'}
          </Blankslate.Heading>
          <Blankslate.Description>
            {errorDescription ?? (
              <>
                The license usage and payment summaries are currently unavailable due to a system error. Try reloading
                the page, or if the problem persists,{' '}
                <a href={contactUrl} style={{textDecoration: 'underline'}}>
                  contact support
                </a>
                .
              </>
            )}
          </Blankslate.Description>
        </Blankslate>
      </div>
    )
  }

  return (
    <div className="mb-3">
      <Stack gap="spacious" className={clsx(styles.stackResponsive)} align="stretch">
        {summaries.map((summary, index) => {
          const key = (summary as React.ReactElement)?.key ?? index
          return (
            <div key={key} className={clsx('Box', styles.box, 'p-3', styles.border)}>
              {summary}
            </div>
          )
        })}
      </Stack>
    </div>
  )
}

try{ SummarySection.displayName ||= 'SummarySection' } catch {}